def syms(a):
 return (np.array_equal(a,np.fliplr(a)),np.array_equal(a,np.flipud(a)),np.array_equal(a,np.rot90(a,2)),np.array_equal(a,a.T),np.array_equal(a,np.fliplr(a).T))
for i,p in enumerate(patterns): print(poss[i][1],labels[i],int(p.sum()),syms(p))

