def encode(a): return ''.join(map(str,a.flatten()))
def canoninfo(p):
 ss=symmetries(p); codes=[encode(s) for s in ss]; ca=min(codes); return ca,[i for i,c in enumerate(codes) if c==ca]
for i,p in enumerate(patterns):
 ca,ori=canoninfo(p)
